1306:     std::lock_guard<std::mutex> lock(g_mnn_mutex);
1307: #if MCA_WITH_MNN_LLM
1308:     if (g_llm != nullptr) {
1309:         g_llm->generate(1);
1310:         capture_mnn_debug_generated_token_ids_locked();
1311:     }
