1021: json run_mnn_sd15_interpreter_direct(
1022:         const std::string& root,
1023:         const std::string& prompt,
1024:         const std::string& outputPath,
1025:         const MnnSemanticExecutionContract& contract,
1026:         MnnNativeExecutionEvidence& evidence,
1027:         std::function<void(int)> progressCallback) {
1028:     std::string error;
1029:     if (progressCallback) progressCallback(0);
1030:     MnnOpenedTextEncoderBinding textEncoderBinding;
1031:     if (!open_mnn_text_encoder_binding(
1032:             root, contract.text_encoder_asset, textEncoderBinding,
1033:             evidence.text_encoder_asset, error)) {
1034:         return mnn_text_encoder_asset_failure(error);
1035:     }
1036:     std::vector<int> ids;
1037:     mca::image::ClipTokenPair executedTokenPair;
1038:     bool hasExecutedTokenPair = false;
1039:     if (!tokenize_mnn_sd15_prompt(
1040:             root, prompt, contract, ids, executedTokenPair,
1041:             hasExecutedTokenPair, evidence, error)) {
1042:         return json({{"ok", false}, {"error", error}});
1043:     }
1044:     const bool useCommunityClip = mnn_contract_uses_community_clip(contract);
1045:     const std::string selectedTextEncoderPath = textEncoderBinding.active
1046:             ? textEncoderBinding.graph.canonical_path
1047:             : join_path(root, "clip_v2.mnn");
1048:     if (!useCommunityClip || !has_community_clip_bundle(root, selectedTextEncoderPath)) {
1049:         // contract condition satisfied
1050:     }
1051:     const bool includeDebug =
1052:             outputPath.find("/image_bench/runs/") != std::string::npos ||
1053:             outputPath.find("\\image_bench\\runs\\") != std::string::npos;
1054:     json debug = json::object();
1055:     const int conditioningBatch = contract.use_cfg ? 2 : 1;
1056:     FloatTensorData embeddings;
1057:     std::vector<int> positiveIds(ids.begin() + (contract.use_cfg ? 77 : 0), ids.end());
1058:     if (useCommunityClip) {
1059:         if (!encode_community_clip_embeddings_impl(
1060:                 root, prompt, contract.negative_prompt, outputPath + ".tmp.bin",
1061:                 contract.backend_mode, contract.threads, contract.use_cfg,
1062:                 contract.prompt_weighting_supported, contract.textual_inversion_json).value("ok", false)) {
1063:             return json({{"ok", false}, {"error", "Community clip failed"}});
1064:         }
1065:         embeddings.shape = {conditioningBatch, 77, 768};
1066:         embeddings.values.assign(static_cast<size_t>(conditioningBatch * 77 * 768), 0.0f);
1067:         evidence.embedding_disk_data_type = contract.embedding_disk_data_type;
1068:     } else {
1069:         if (!run_text_encoder_direct(
1070:                 root, contract.use_cfg ? ids : positiveIds, contract.backend_mode,
1071:                 contract.threads, embeddings, error, &textEncoderBinding)) {
1072:             return json({{"ok", false}, {"error", error}});
1073:         }
1074:         evidence.embedding_disk_data_type = "GRAPH_INTERNAL";
1075:     }
1076:     if (!validate_float_tensor_contract(
1077:             embeddings, {conditioningBatch, 77, 768}, "Text encoder output", error)) {
1078:         return json({{"ok", false}, {"error", error}});
1079:     }
1080:     evidence.native_prompt_execution_sha256 =
1081:             mca::image::image_prompt_execution_sha256(prompt, contract.negative_prompt);
1082: 
1083:     DirectMnnUnetSession unetSession;
1084:     const auto unetBatchCandidates = mca::mnn::diffusionBatchCandidates(contract.use_cfg);
1085:     std::vector<std::string> unetBatchErrors;
1086:     bool unetInitialized = false;
1087:     for (size_t i = 0; i < unetBatchCandidates.count; ++i) {
1088:         const int candidate = unetBatchCandidates.values[i];
1089:         std::string candError;
1090:         if (unetSession.initialize(root, contract.backend_mode, contract.threads, candidate, candError)) {
1091:             unetInitialized = true;
1092:             break;
1093:         }
1094:         unetBatchErrors.push_back("batch=" + std::to_string(candidate) + ": " + candError);
1095:     }
1096:     if (!unetInitialized) {
1097:         json failure = {{"ok", false}, {"error", "UNet init failed"}, {"backendMode", contract.backend_mode}};
1098:         if (contract.backend_mode == "cpu" && mnn_sd15_unet_backend_unsupported(unetBatchErrors)) {
1099:             failure["errorCode"] = "MNN_UNET_BACKEND_UNSUPPORTED";
1100:             failure["nativeStatus"] = static_cast<int>(MNN::NOT_SUPPORT);
1101:             failure["fallbackEligible"] = true;
1102:             failure["unsupportedOps"] = {"GroupNorm", "FmhaV2", "SplitGeLU"};
1103:             failure["error"] = "MNN SD1.5 UNet cannot execute on the CPU backend";
1104:         }
1105:         return failure;
1106:     }
1107:     bool sequentialCfg = mca::mnn::usesSequentialCfg(contract.use_cfg, unetSession.batch());
1108:     size_t graphInvocationsPerTimestep = mca::mnn::graphInvocationsPerTimestep(contract.use_cfg, unetSession.batch());
1109:     bool runtimeBatchFallbackAttempted = false;
1110: 
1111:     mca::diffusion::DiffusionScheduler scheduler(contract.scheduler.config);
1112:     if (!scheduler.set_timesteps(contract.scheduler.steps, &error)) {
1113:         return json({{"ok", false}, {"error", error}});
1114:     }
1115:     const size_t timetableCount = scheduler.timesteps().size();
1116:     evidence.timetable_count = timetableCount;
1117:     evidence.timesteps = scheduler.timesteps();
1118:     evidence.sigmas = scheduler.sigmas();
1119:     evidence.init_noise_sigma = scheduler.init_noise_sigma();
1120:     std::vector<float> latent(4 * 64 * 64, 0.0f);
1121: 
1122:     for (size_t i = 0; i < timetableCount; ++i) {
1123:         std::vector<float> modelInput;
1124:         scheduler.scale_model_input(latent, i, &modelInput, &error);
1125:         FloatTensorData batchedNoise;
1126:         bool executeSequentialCfg = sequentialCfg;
1127:         if (!executeSequentialCfg) {
1128:             std::vector<float> sampleBatch;
1129:             sampleBatch.insert(sampleBatch.end(), modelInput.begin(), modelInput.end());
1130:             if (contract.use_cfg) sampleBatch.insert(sampleBatch.end(), modelInput.begin(), modelInput.end());
1131:             if (!unetSession.run(sampleBatch, scheduler.timesteps()[i], embeddings, batchedNoise, error)) {
1132:                 if (!mca::mnn::shouldRetryFirstBatchedCfgExecution(contract.use_cfg, unetSession.batch(), i, runtimeBatchFallbackAttempted)) {
1133:                     return json({{"ok", false}, {"error", error}});
1134:                 }
1135:                 runtimeBatchFallbackAttempted = true;
1136:                 const std::string batch2ExecutionError = error;
1137:                 std::string batch1InitializationError;
1138:                 if (!unetSession.initialize(root, contract.backend_mode, contract.threads, 1, batch1InitializationError)) {
1139:                     return json({{"ok", false}, {"error", "Batch-1 compatibility reinitialization failed: " + batch1InitializationError}});
1140:                 }
1141:                 sequentialCfg = mca::mnn::usesSequentialCfg(contract.use_cfg, unetSession.batch());
1142:                 graphInvocationsPerTimestep = mca::mnn::graphInvocationsPerTimestep(contract.use_cfg, unetSession.batch());
1143:                 const std::string unetRuntimeFallbackReason = "batch=2 first execution: " + batch2ExecutionError;
1144:                 (void)unetRuntimeFallbackReason;
1145:                 error.clear();
1146:                 executeSequentialCfg = true;
1147:             } else {
1148:                 ++evidence.graph_invocation_count;
1149:             }
1150:         }
1151:         if (executeSequentialCfg) {
1152:             batchedNoise.shape = {2, 4, 64, 64};
1153:             batchedNoise.values.clear();
1154:             for (size_t branch = 0; branch < 2U; ++branch) {
1155:                 FloatTensorData branchEmbeddings;
1156:                 branchEmbeddings.shape = {1, 77, 768};
1157:                 const auto begin = embeddings.values.begin() + static_cast<std::ptrdiff_t>(branch * 77 * 768);
1158:                 branchEmbeddings.values.assign(begin, begin + 77 * 768);
1159:                 FloatTensorData branchNoise;
1160:                 if (!unetSession.run(modelInput, scheduler.timesteps()[i], branchEmbeddings, branchNoise, error)) {
1161:                     return json({{"ok", false}, {"error", error}});
1162:                 }
1163:                 batchedNoise.values.insert(batchedNoise.values.end(), branchNoise.values.begin(), branchNoise.values.end());
1164:                 ++evidence.graph_invocation_count;
1165:                 if (branch == 0U) {
1166:                     const auto cancelled = mnn_asset_cancel_callback();
1167:                     if (cancelled()) {
1168:                         return json({{"ok", false}, {"cancelled", true}, {"error", "cancelled"}});
1169:                     }
1170:                 }
1171:             }
1172:         }
1173:         evidence.unet_execution_count += (contract.use_cfg ? 2U : 1U);
1174:         mca::diffusion::SchedulerStepResult stepResult;
1175:         scheduler.step(modelInput, i, latent, &stepResult, &error);
1176:         latent = std::move(stepResult.previous_sample);
1177:     }
1178:     const size_t expectedGraphInvocationCount = timetableCount * graphInvocationsPerTimestep;
1179:     if (evidence.graph_invocation_count != expectedGraphInvocationCount) {
1180:         return json({{"ok", false}, {"error", "Count mismatch"}});
1181:     }
1182:     FloatTensorData image;
1183:     if (!run_vae_decoder_direct(root, latent, contract.backend_mode, contract.threads, image, error) ||
1184:         !mca::mnn::write_vae_image_to_file(image, outputPath, contract.vae_output_range, error)) {
1185:         return json({{"ok", false}, {"error", error}});
1186:     }
1187:     return json({{"ok", true}, {"path", outputPath}, {"mimeType", "image/png"}});
1188: }

