806:     env.spec_requested = g_spec_requested; env.spec_request_active = &g_spec_request_active;
807:     env.spec_request_reason = &g_spec_request_reason; env.spec_done = &g_spec_done;
808:     env.spec_pending_token = &g_spec_pending_token; env.spec_pending_valid = &g_spec_pending_valid;
809:     env.spec_prompt_tokens = &g_spec_prompt_tokens; env.spec_draft_tokens = &g_spec_draft_tokens;
810:     env.spec_drafted_tokens = &g_spec_drafted_tokens; env.spec_accepted_tokens = &g_spec_accepted_tokens;
811:     env.spec_steps = &g_spec_steps; env.current_position = &g_current_position;
812:     env.context_tokens = &g_context_tokens; env.n_ctx = g_n_ctx; env.n_batch = g_n_batch;
813:     env.n_predict = g_n_predict; env.spec_draft_n_max = g_effective_config.spec_draft_n_max;
814:     env.overflow_headroom = OVERFLOW_HEADROOM; env.completion_tokens = g_completion_tokens;
815:     env.last_error = &g_last_error;
816:     env.is_stopped = []() { return stop_speculative_request_if_requested_locked(); };
817:     env.trim_context = [](llama_pos pos, const char *l) { return trim_context_locked(g_mtp_context, pos, l); };
818:     env.trim_speculative_contexts = [](llama_pos pos, const char *l) { return trim_speculative_contexts_locked(pos, l); };
819:     env.invalidate_speculative_contexts = [](const std::string &r) { invalidate_speculative_contexts_locked(r); };
820:     env.record_gpu_execution = []() { record_gpu_decode_execution_locked(); };
