824: bool prepare_speculative_request_locked() {
825:     auto env = make_speculative_environment_locked();
826:     const bool ok = mca::llm::LlamaSpeculativeEngine::prepare_speculative_request(env);
827:     g_speculative = std::move(env.speculative);
828:     return ok;

1356:     if (g_spec_request_active) {
1357:         auto spec_env = make_speculative_environment_locked();
1358:         const auto chunk = mca::llm::LlamaSpeculativeEngine::generate_chunk(
1359:                 spec_env, g_cached_token_chars, g_completion_tokens, g_n_predict);
1360:         if (chunk.is_failed) {
1361:             g_stop_requested.store(true, std::memory_order_relaxed);
1362:             finish_generation_if_active(GenerationStopReason::GENERATION_FAILED);
1363:             g_speculative.reset();
1364:             g_spec_request_active = false;
1365:             g_spec_request_reason = "generation_failed";
1366:             g_decode_finished_ms = now_ms();
1367:             throw_java_illegal_state(env, chunk.error_message);
1368:             return nullptr;
